import sys,numpy as np
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); o=r.get_obs(cameras=['front','side','top'],include_depth=True)
cal=o.meta['cameras']; fx=230.517855; cx=cy=160

def world(cam,u,v,d):
 p=np.array([(u-160)*d/fx,-(v-120)*d/fx,-d,1.]); return np.array(cal[cam]['cam2world_gl'])@p
for cam in ['front','side','top']:
 im=np.array(o.last[cam]); d=np.squeeze(np.array(o.depth[cam],float)); pts=[]; pix=[]
 for v in range(90,170):
  for u in range(80,220):
   R,G,B=im[v,u]
   if max(R,G,B)<125 and (max(R,G,B)-min(R,G,B))<28 and d[v,u]<1.3:
    P=world(cam,u,v,d[v,u])
    if .525<P[2]<.61:
     pts.append(P[:3]);pix.append([u,v,R,int(d[v,u]*1000)])
 pts=np.array(pts)
 print('\n',cam,'n',len(pts))
 if len(pts):
  for ax in range(3): print('xyz'[ax],np.quantile(pts[:,ax],[0,.1,.25,.5,.75,.9,1]).round(3))
  pix=np.array(pix); print('pix bounds',pix.min(0),pix.max(0))
  # coarse 3d buckets count
  for x in np.arange(-.2,.25,.05):
   for y in np.arange(-.1,.20,.05):
    sel=(pts[:,0]>=x)&(pts[:,0]<x+.05)&(pts[:,1]>=y)&(pts[:,1]<y+.05)
    if sel.sum()>5: print('  cell',round(x,2),round(y,2),int(sel.sum()),'z',np.median(pts[sel,2]).round(3))
